(async () => {
  // ── CSS ──────────────────────────────────────────────────────────────────
  const _CSS_ID = "jsd-item-journal-css";
  if (!document.getElementById(_CSS_ID)) {
    const _s = document.createElement("style");
    _s.id = _CSS_ID;
    _s.textContent = `
      #ij-dialog .window-content { padding: 0 !important; }
      #ij-root { background: linear-gradient(150deg,#1e1812,#261e14); color:#f5e6d3; font-family:'Segoe UI',Tahoma,sans-serif; font-size:13px; padding:14px; }
      #ij-root p { color:#c9a876; font-size:12px; margin-bottom:8px; }
      #ij-folder-list { background:#2a2018; border:1px solid #4a3a28; border-radius:6px; max-height:260px; overflow-y:auto; padding:8px; margin-bottom:8px; }
      #ij-folder-list::-webkit-scrollbar { width:5px; }
      #ij-folder-list::-webkit-scrollbar-track { background:#1a1410; }
      #ij-folder-list::-webkit-scrollbar-thumb { background:#6a4a2a; border-radius:3px; }
      #ij-folder-list::-webkit-scrollbar-thumb:hover { background:#d4a574; }
      #ij-root .ij-folder-row { align-items:center; border-radius:4px; display:flex; gap:8px; padding:4px 4px; }
      #ij-root .ij-folder-row:hover { background:rgba(212,165,116,0.08); }
      #ij-root .ij-folder-row input[type="checkbox"] { accent-color:#d4a574; cursor:pointer; flex-shrink:0; height:14px; width:14px; }
      #ij-root .ij-folder-row strong { color:#f5d9a8; }
      #ij-root .ij-count { color:#c9a876; font-size:11px; }
      #ij-root .ij-links { display:flex; gap:14px; justify-content:flex-end; margin-top:2px; }
      #ij-root .ij-link { color:#d4a574; cursor:pointer; font-size:11px; text-decoration:none; transition:color 0.12s; }
      #ij-root .ij-link:hover { color:#e8c090; text-decoration:underline; }
    `;
    document.head.appendChild(_s);
  }

  // ── Data ─────────────────────────────────────────────────────────────────
  const items = game.items.contents;
  if (items.length === 0) { ui.notifications.warn("Nenhum item encontrado no mundo."); return; }

  function getRootFolderName(folderId) {
    if (!folderId) return "Sem Pasta";
    let folder = game.folders.get(folderId);
    while (folder && folder.folder) folder = game.folders.get(folder.folder.id);
    return folder ? folder.name : "Sem Pasta";
  }

  const itemsByFolder = {};
  for (const item of items) {
    const rootName = getRootFolderName(item.folder?.id);
    if (!itemsByFolder[rootName]) itemsByFolder[rootName] = [];
    itemsByFolder[rootName].push(item);
  }
  const folderNames = Object.keys(itemsByFolder).sort();

  // ── State (updated by render-callback listeners) ─────────────────────────
  const selectedFolders = new Set(folderNames); // all pre-selected

  // ── HTML ─────────────────────────────────────────────────────────────────
  const checkboxesHTML = folderNames.map(folder => `
    <div class="ij-folder-row">
      <input type="checkbox" name="selectedFolders" value="${folder}" checked>
      <span><strong>${folder}</strong> <span class="ij-count">(${itemsByFolder[folder].length} itens)</span></span>
    </div>`).join("");

  const content = `
    <div id="ij-root">
      <p>Selecione quais pastas raiz deseja exportar para Journals:</p>
      <div id="ij-folder-list">${checkboxesHTML}</div>
      <div class="ij-links">
        <a class="ij-link" id="ij-select-all">Marcar Todos</a>
        <a class="ij-link" id="ij-deselect-all">Desmarcar Todos</a>
      </div>
    </div>`;

  // ── Dialog ────────────────────────────────────────────────────────────────
  const result = await foundry.applications.api.DialogV2.wait({
    window: { title: "Exportar Itens para Journal", id: "ij-dialog" },
    content,
    buttons: [
      {
        action: "export", label: "Gerar Journals", icon: "fas fa-book", default: true,
        callback: (event, button) => {
          const form = button.closest("form");
          return [...form.querySelectorAll('input[name="selectedFolders"]:checked')].map(cb => cb.value);
        }
      },
      { action: "cancel", label: "Cancelar", icon: "fas fa-times", callback: () => null }
    ],
    render: (_event, dialog) => {
      const el = dialog.element;
      el.querySelector("#ij-select-all")?.addEventListener("click", () => {
        el.querySelectorAll('input[name="selectedFolders"]').forEach(cb => { cb.checked = true; selectedFolders.add(cb.value); });
      });
      el.querySelector("#ij-deselect-all")?.addEventListener("click", () => {
        el.querySelectorAll('input[name="selectedFolders"]').forEach(cb => { cb.checked = false; selectedFolders.delete(cb.value); });
      });
    },
    rejectClose: false,
  });

  if (!result || result.length === 0) {
    if (result !== null) ui.notifications.warn("Nenhuma pasta foi selecionada.");
    return;
  }

  // ── Export ────────────────────────────────────────────────────────────────
  ui.notifications.info(`Processando ${result.length} pasta(s)...`);
  const IMAGE_SIZE = "180px";
  let createdCount = 0;

  for (const folderName of result) {
    const folderItems = [...itemsByFolder[folderName]].sort((a, b) => a.name.localeCompare(b.name));
    const pages = folderItems.map(item => {
      const description = item.system?.description?.value || item.system?.description || "<em>Sem descrição.</em>";
      const imgHTML = item.img && item.img !== "icons/svg/item-bag.svg"
        ? `<div style="text-align:center;margin-bottom:15px;"><img src="${item.img}" style="border:none;max-width:${IMAGE_SIZE};width:100%;height:auto;display:inline-block;filter:drop-shadow(0px 2px 5px rgba(0,0,0,0.5));"/></div>`
        : "";
      return {
        name: item.name, type: "text",
        text: { content: `${imgHTML}<div class="item-description">${description}</div>`, format: CONST.JOURNAL_ENTRY_PAGE_FORMATS.HTML }
      };
    });
    await JournalEntry.create({ name: `Catálogo - ${folderName}`, pages });
    createdCount++;
  }

  ui.notifications.info(`Pronto! Criados ${createdCount} Journal(s) com sucesso.`);
})();

// MACRO: Reset Rotation + Lock em todos os tokens (todas as cenas)
(async () => {
  let totalTokens = 0;
  let totalCenas = 0;

  // --- Bloco 1: Tokens colocados em cenas ---
  for (const scene of game.scenes) {
    const updates = [];

    for (const token of scene.tokens) {
      if (token.rotation !== 0 || !token.lockRotation) {
        updates.push({ _id: token.id, rotation: 0, lockRotation: true });
      }
    }

    if (updates.length) {
      await scene.updateEmbeddedDocuments("Token", updates);
      totalTokens += updates.length;
      totalCenas++;
      console.log(`[RotationFix] "${scene.name}": ${updates.length} token(s) corrigidos.`);
    }
  }

  // --- Bloco 2: Prototype tokens nos atores (descomente se quiser) ---
  /*
  for (const actor of game.actors) {
    const pt = actor.prototypeToken;
    if (pt.rotation !== 0 || !pt.lockRotation) {
      await actor.update({
        "prototypeToken.rotation": 0,
        "prototypeToken.lockRotation": true
      });
      console.log(`[RotationFix] Prototype "${actor.name}" corrigido.`);
    }
  }
  */

  ui.notifications.info(
    `Rotation Fix: ${totalTokens} token(s) corrigidos em ${totalCenas} cena(s).`
  );
})();

/**
 * Editor de Configuração de Cenas em Massa — Foundry VTT V14
 * Interface Avançada com Árvore de Pastas Colapsável
 */
(async () => {

  // ═══════════════════════════════════════════════════════════════════════════
  // CSS Dedicado (Estilo Premium Escuro)
  // ═══════════════════════════════════════════════════════════════════════════
  (() => {
    const CSS_ID = "macro-mass-scenes-css";
    if (document.getElementById(CSS_ID)) return;
    const s = document.createElement("style");
    s.id = CSS_ID;
    s.textContent = `
      #macro-scenes-window .form-footer { display: none !important; }
      #ms-root * { box-sizing: border-box; }

      #ms-root {
        display: flex; flex-direction: column;
        background: linear-gradient(160deg, #1a1410 0%, #2a2018 100%);
        color: #f5e6d3; font-family: 'Segoe UI', Tahoma, sans-serif;
        font-size: 13px; overflow: hidden;
      }
      #ms-root .ms-header {
        background: linear-gradient(135deg, #3a2510, #2a1a08);
        padding: 11px 16px 9px; border-bottom: 2px solid #d4a574; flex-shrink: 0;
      }
      #ms-root .ms-header h2 {
        margin: 0 0 2px; font-size: 15px; font-weight: 800;
        letter-spacing: 1.5px; text-transform: uppercase;
        color: #f5d9a8; text-shadow: 0 2px 4px rgba(0,0,0,0.6);
      }
      #ms-root .ms-header p { margin: 0; font-size: 11px; color: #c9a876; }

      #ms-root .ms-body {
        display: flex; flex: 1; overflow: hidden;
      }

      /* Painel Esquerdo: Árvore */
      #ms-root .ms-panel-left {
        flex: 1.2; display: flex; flex-direction: column;
        border-right: 1px solid #4a3a28; overflow: hidden;
      }
      #ms-root .ms-toolbar {
        padding: 6px 12px; display: flex; gap: 6px; align-items: center;
        background: #1a1410; border-bottom: 1px solid #2a2018; flex-shrink: 0;
      }
      #ms-root .ms-btn-sm {
        padding: 3px 10px; border-radius: 5px;
        border: 1px solid #6a4a2a; background: #4a3a28;
        color: #e8d5c0; font-size: 11px; font-weight: 700;
        cursor: pointer; transition: all 0.12s;
      }
      #ms-root .ms-btn-sm:hover { background: #6a4a2a; color: #f5d9a8; }
      #ms-root .ms-sel-count { flex: 1; font-size: 11px; color: #c9a876; text-align: right; }

      #ms-root .ms-tree {
        flex: 1; overflow-y: auto; overflow-x: hidden;
        padding: 8px 10px; background: rgba(0,0,0,0.2);
      }
      #ms-root .ms-tree::-webkit-scrollbar { width: 6px; }
      #ms-root .ms-tree::-webkit-scrollbar-track { background: #1a1410; }
      #ms-root .ms-tree::-webkit-scrollbar-thumb { background: #4a3a28; border-radius: 3px; }
      #ms-root .ms-tree::-webkit-scrollbar-thumb:hover { background: #d4a574; }

      #ms-root .ms-tree ul { list-style: none; padding-left: 16px; margin: 2px 0; }
      #ms-root .ms-tree > ul { padding-left: 0; }
      #ms-root .ms-tree li { margin: 2px 0; }

      #ms-root .ms-row {
        display: flex; align-items: center; gap: 5px;
        padding: 4px 6px; border-radius: 4px; transition: background 0.1s;
      }
      #ms-root .ms-row:hover { background: rgba(212, 165, 116, 0.08); }
      #ms-root .ms-row input[type="checkbox"] {
        width: 14px; height: 14px; accent-color: #d4a574; cursor: pointer; flex-shrink: 0; margin: 0;
      }
      #ms-root .ms-toggle {
        width: 14px; font-size: 9px; color: #c9a876; cursor: pointer;
        flex-shrink: 0; text-align: center; user-select: none;
      }
      #ms-root .ms-toggle:hover { color: #d4a574; }
      #ms-root .ms-icon { font-size: 12px; color: #d4a574; flex-shrink: 0; width: 14px; text-align: center; }
      #ms-root .ms-icon.scene-icon { color: #c9a876; }
      #ms-root .ms-name { font-size: 13px; user-select: none; cursor: default; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
      #ms-root .ms-name.parent { font-weight: 700; color: #f5d9a8; }
      #ms-root .ms-subtree { display: none; }
      #ms-root .ms-subtree.open { display: block; }

      /* Painel Direito: Opções */
      #ms-root .ms-panel-right {
        flex: 1; padding: 12px 16px; display: flex; flex-direction: column; gap: 10px;
        background: rgba(15, 23, 42, 0.4); overflow-y: auto;
      }
      #ms-root .ms-panel-right h3 {
        margin: 0 0 4px 0; font-size: 13px; font-weight: 700;
        text-transform: uppercase; color: #d4a574; letter-spacing: 0.5px;
        border-bottom: 1px solid #4a3a28; padding-bottom: 4px;
      }
      #ms-root .ms-opt-row {
        display: flex; align-items: flex-start; gap: 8px; padding: 5px 0;
      }
      #ms-root .ms-opt-row input[type="checkbox"] {
        width: 15px; height: 15px; accent-color: #d4a574; cursor: pointer; flex-shrink: 0; margin-top: 2px;
      }
      #ms-root .ms-opt-label { cursor: pointer; user-select: none; line-height: 1.3; color: #e8d5c0; }
      #ms-root .ms-opt-label strong { color: #f5d9a8; }

      /* Footer */
      #ms-root .ms-footer {
        flex-shrink: 0; padding: 10px 14px;
        border-top: 2px solid #d4a574; background: #1a1410;
        display: flex; gap: 8px; align-items: center;
      }
      #ms-root .ms-btn-cancel {
        padding: 7px 14px; border: 1.5px solid #6a4a2a; border-radius: 6px;
        background: #2a2018; color: #c9a876; font-size: 13px; font-weight: 700;
        cursor: pointer; transition: all 0.12s;
      }
      #ms-root .ms-btn-cancel:hover { background: #4a3a28; color: #f5d9a8; }
      #ms-root .ms-btn-primary {
        padding: 7px 20px; border: none; border-radius: 6px;
        background: linear-gradient(135deg, #d4a574, #c99456);
        color: #1a1410; font-size: 13px; font-weight: 800;
        cursor: pointer; transition: all 0.12s; text-transform: uppercase; margin-left: auto;
      }
      #ms-root .ms-btn-primary:hover {
        background: linear-gradient(135deg, #e8c090, #d4a574);
        transform: translateY(-1px); box-shadow: 0 3px 8px rgba(212, 165, 116, 0.3);
      }
    `;
    document.head.appendChild(s);
  })();

  // ═══════════════════════════════════════════════════════════════════════════
  // Estado Persistido (LocalStorage)
  // ═══════════════════════════════════════════════════════════════════════════
  const lastSelectedScenes = JSON.parse(localStorage.getItem("ms-selected-scenes") || "[]");
  const lastOpenFolders    = JSON.parse(localStorage.getItem("ms-open-folders")    || "[]");
  const lastOptions        = JSON.parse(localStorage.getItem("ms-checked-options") || "{}");

  // ═══════════════════════════════════════════════════════════════════════════
  // Organização dos Dados das Cenas
  // ═══════════════════════════════════════════════════════════════════════════
  const allSceneFolders = game.folders
    .filter(f => f.type === "Scene")
    .sort((a, b) => a.name.localeCompare(b.name));

  const scenesWithoutFolder = game.scenes.contents.filter(s => !s.folder);

  // ═══════════════════════════════════════════════════════════════════════════
  // Construtor Recursivo da Árvore HTML
  // ═══════════════════════════════════════════════════════════════════════════
  function buildTreeHTML(parentId = null) {
    const childrenFolders = allSceneFolders.filter(f => (f.folder?.id ?? null) === parentId);
    const targetScenes = game.scenes.contents.filter(s => (s.folder?.id ?? null) === parentId);

    if (!childrenFolders.length && !targetScenes.length) return "";

    let html = "<ul>";

    // 1. Renderiza Pastas filhas
    for (const folder of childrenFolders) {
      const subTree = buildTreeHTML(folder.id);
      const hasSub = !!subTree;
      const isOpen = lastOpenFolders.includes(folder.id) ? " open" : "";

      html += `<li>
        <div class="ms-row folder-row">
          ${hasSub ? `<span class="ms-toggle" data-fid="${folder.id}">▶</span>` : `<span class="ms-toggle"></span>`}
          <i class="fa-solid ${isOpen ? "fa-folder-open" : "fa-folder"} ms-icon"></i>
          <span class="ms-name parent">${folder.name}</span>
        </div>
        ${hasSub ? `<div class="ms-subtree${isOpen}" data-fid="${folder.id}">${subTree}</div>` : ""}
      </li>`;
    }

    // 2. Renderiza Cenas contidas nesta camada
    for (const scene of targetScenes) {
      const isChecked = lastSelectedScenes.includes(scene.id) ? "checked" : "";
      html += `<li>
        <div class="ms-row scene-row">
          <span class="ms-toggle"></span>
          <input type="checkbox" class="scene-check" value="${scene.id}" ${isChecked}>
          <i class="fa-solid fa-map ms-icon scene-icon"></i>
          <span class="ms-name" title="${scene.name}">${scene.name}</span>
        </div>
      </li>`;
    }

    html += "</ul>";
    return html;
  }

  // Montagem inicial da árvore de pastas e cenas soltas
  let fullTreeHtml = buildTreeHTML(null);
  if (scenesWithoutFolder.length > 0 && !fullTreeHtml.includes("scene-check")) {
    // Se houverem apenas cenas na raiz sem nenhuma pasta criada
    fullTreeHtml = "<ul>" + scenesWithoutFolder.map(scene => {
      const isChecked = lastSelectedScenes.includes(scene.id) ? "checked" : "";
      return `<li>
        <div class="ms-row scene-row">
          <span class="ms-toggle"></span>
          <input type="checkbox" class="scene-check" value="${scene.id}" ${isChecked}>
          <i class="fa-solid fa-map ms-icon scene-icon"></i>
          <span class="ms-name" title="${scene.name}">${scene.name}</span>
        </div>
      </li>`;
    }).join("") + "</ul>";
  }

  // Helper para checar valores salvos das opções da checklist
  const optCheck = (key) => lastOptions[key] ? "checked" : "";

  // ═══════════════════════════════════════════════════════════════════════════
  // Layout Principal do Painel
  // ═══════════════════════════════════════════════════════════════════════════
  const mainContent = `
    <div id="ms-root">
      <div class="ms-header">
        <h2>🎬 Editor de Cenas e Transições em Massa</h2>
        <p>Navegue pelas pastas, selecione alvos e defina parâmetros do mundo.</p>
      </div>

      <div class="ms-body">
        <div class="ms-panel-left">
          <div class="ms-toolbar">
            <button type="button" class="ms-btn-sm" id="ms-all">✔ Todas</button>
            <button type="button" class="ms-btn-sm" id="ms-none">✘ Limpar</button>
            <button type="button" class="ms-btn-sm" id="ms-expand"> Expandir</button>
            <button type="button" class="ms-btn-sm" id="ms-collapse"> Recolher</button>
            <span class="ms-sel-count" id="ms-sel-count">0 selecionadas</span>
          </div>
          <div class="ms-tree" id="ms-tree">
            ${fullTreeHtml || '<p style="color:#c9a876;padding:10px;">Nenhuma cena mapeada no mundo.</p>'}
          </div>
        </div>

        <div class="ms-panel-right">
          <h3>⚙ Checklist de Modificações</h3>

          <div class="ms-opt-row">
            <input type="checkbox" id="opt-fade" ${optCheck("fade")}>
            <label class="ms-opt-label" for="opt-fade">Aplicar <strong>Scene Transition (Fade)</strong><br><small style="color:#c9a876;">Duração de 1000ms padrão</small></label>
          </div>

          <div class="ms-opt-row">
            <input type="checkbox" id="opt-gridless" ${optCheck("gridless")}>
            <label class="ms-opt-label" for="opt-gridless">Forçar Modo <strong>Gridless</strong><br><small style="color:#c9a876;">Tipo de Grid configurado como 0</small></label>
          </div>

          <div class="ms-opt-row">
            <input type="checkbox" id="opt-bgcolor" ${optCheck("bgcolor")}>
            <label class="ms-opt-label" for="opt-bgcolor">Cor de Fundo Preta <strong>(#000000)</strong></label>
          </div>

          <div class="ms-opt-row">
            <input type="checkbox" id="opt-sharedfog" ${optCheck("sharedfog")}>
            <label class="ms-opt-label" for="opt-sharedfog">Fog of War: <strong>Shared Exploration</strong><br><small style="color:#c9a876;">Modo de exploração compartilhado</small></label>
          </div>

          <div class="ms-opt-row">
            <input type="checkbox" id="opt-tokenvision" ${optCheck("tokenvision")}>
            <label class="ms-opt-label" for="opt-tokenvision">Habilitar Visão do Token <strong>(Token Vision)</strong></label>
          </div>

          <div class="ms-opt-row">
            <input type="checkbox" id="opt-globallight" ${optCheck("globallight")}>
            <label class="ms-opt-label" for="opt-globallight">Habilitar <strong>Iluminação Global (Global Light)</strong></label>
          </div>

          <div class="ms-opt-row">
            <input type="checkbox" id="opt-bgvolume" ${optCheck("bgvolume")}>
            <label class="ms-opt-label" for="opt-bgvolume">Zerar Volume de Trilha de Fundo <strong>(Volume 0)</strong></label>
          </div>
        </div>
      </div>

      <div class="ms-footer">
        <button type="button" class="ms-btn-cancel" id="ms-cancel">Cancelar</button>
        <button type="button" class="ms-btn-primary" id="ms-execute">⚡ Executar em Massa</button>
      </div>
    </div>
  `;

  // ═══════════════════════════════════════════════════════════════════════════
  // Execução e Renderização com DialogV2
  // ═══════════════════════════════════════════════════════════════════════════
  await foundry.applications.api.DialogV2.wait({
    window: { title: "Gerenciador de Cenas Avançado", id: "macro-scenes-window" },
    content: mainContent,
    buttons: [{ action: "noop", label: "–", callback: () => null }], // Ocultado via CSS

    render: (_event, dialog) => {
      const el = dialog.element;

      // Injeta e limpa as restrições nativas do Foundry Window
      el.querySelector(".form-footer")?.style.setProperty("display", "none", "important");
      const wc = el.querySelector(".window-content");
      if (wc) {
        wc.style.setProperty("padding", "0", "important");
        wc.style.setProperty("overflow", "hidden", "important");
      }

      // Auto cálculo dinâmico de altura responsiva
      function resizeLayout() {
        const wcEl = el.querySelector(".window-content");
        const root = el.querySelector("#ms-root");
        if (!wcEl || !root) return;
        root.style.setProperty("height", wcEl.clientHeight + "px", "important");
      }
      requestAnimationFrame(resizeLayout);
      new ResizeObserver(resizeLayout).observe(el);

      // Controle de abertura manual de pastas (Colapsáveis)
      el.querySelectorAll(".ms-toggle[data-fid]").forEach(toggle => {
        const folderId = toggle.dataset.fid;
        const subTree = el.querySelector(`.ms-subtree[data-fid="${folderId}"]`);
        const folderIcon = toggle.closest(".ms-row")?.querySelector(".ms-icon");

        if (subTree && subTree.classList.contains("open")) toggle.textContent = "▼";

        toggle.addEventListener("click", () => {
          const isOpen = subTree.classList.toggle("open");
          toggle.textContent = isOpen ? "▼" : "▶";
          if (folderIcon) {
            if (isOpen) {
              folderIcon.classList.remove("fa-folder");
              folderIcon.classList.add("fa-folder-open");
            } else {
              folderIcon.classList.remove("fa-folder-open");
              folderIcon.classList.add("fa-folder");
            }
          }
        });
      });

      // Botões Globais de Expandir / Recolher Pastas
      el.querySelector("#ms-expand")?.addEventListener("click", () => {
        el.querySelectorAll(".ms-subtree").forEach(s => s.classList.add("open"));
        el.querySelectorAll(".ms-toggle[data-fid]").forEach(t => t.textContent = "▼");
        el.querySelectorAll(".folder-row .ms-icon").forEach(i => { i.classList.remove("fa-folder"); i.classList.add("fa-folder-open"); });
      });
      el.querySelector("#ms-collapse")?.addEventListener("click", () => {
        el.querySelectorAll(".ms-subtree").forEach(s => s.classList.remove("open"));
        el.querySelectorAll(".ms-toggle[data-fid]").forEach(t => t.textContent = "▶");
        el.querySelectorAll(".folder-row .ms-icon").forEach(i => { i.classList.remove("fa-folder-open"); i.classList.add("fa-folder"); });
      });

      // Contador dinâmico de Cenas ativas no topo
      function updateSelectionCount() {
        const checkedCount = el.querySelectorAll(".scene-check:checked").length;
        const display = el.querySelector("#ms-sel-count");
        if (display) display.textContent = `${checkedCount} cena(s) selecionada(s)`;
      }
      el.querySelectorAll(".scene-check").forEach(cb => cb.addEventListener("change", updateSelectionCount));
      updateSelectionCount();

      // Botões Rápidos de Seleção de Cenas
      el.querySelector("#ms-all")?.addEventListener("click", () => {
        el.querySelectorAll(".scene-check").forEach(cb => cb.checked = true);
        updateSelectionCount();
      });
      el.querySelector("#ms-none")?.addEventListener("click", () => {
        el.querySelectorAll(".scene-check").forEach(cb => cb.checked = false);
        updateSelectionCount();
      });

      // Ação: Cancelar operação
      el.querySelector("#ms-cancel")?.addEventListener("click", () => dialog.close());

      // Ação: Executar Modificações em Massa
      el.querySelector("#ms-execute")?.addEventListener("click", async () => {
        const selectedIds = [...el.querySelectorAll(".scene-check:checked")].map(cb => cb.value);

        if (!selectedIds.length) {
          ui.notifications.warn("Por favor, selecione pelo menos uma cena na árvore lateral.");
          return;
        }

        // Leitura de estados da Checklist
        const runFade        = el.querySelector("#opt-fade").checked;
        const runGridless    = el.querySelector("#opt-gridless").checked;
        const runBgColor     = el.querySelector("#opt-bgcolor").checked;
        const runSharedFog   = el.querySelector("#opt-sharedfog").checked;
        const runTokenVision = el.querySelector("#opt-tokenvision").checked;
        const runGlobalLight = el.querySelector("#opt-globallight").checked;
        const runBgVolume    = el.querySelector("#opt-bgvolume").checked;

        if (!runFade && !runGridless && !runBgColor && !runSharedFog && !runTokenVision && !runGlobalLight && !runBgVolume) {
          ui.notifications.warn("Nenhuma opção foi marcada na checklist para ser alterada.");
          return;
        }

        // Salva estado atual para reabrir no mesmo ponto na próxima execução
        const currentOpenFolders = [...el.querySelectorAll(".ms-subtree.open")].map(s => s.dataset.fid);
        const savedOptions = {
          fade: runFade, gridless: runGridless, bgcolor: runBgColor, sharedfog: runSharedFog,
          tokenvision: runTokenVision, globallight: runGlobalLight, bgvolume: runBgVolume
        };
        localStorage.setItem("ms-selected-scenes", JSON.stringify(selectedIds));
        localStorage.setItem("ms-open-folders",    JSON.stringify(currentOpenFolders));
        localStorage.setItem("ms-checked-options", JSON.stringify(savedOptions));

        // Constroi objeto de alteração dinamicamente conforme checklist
        let updateData = {};
        if (runFade) {
          updateData["transition"] = { type: "fade", duration: 1000, activeOnly: true };
        }
        if (runGridless)    updateData["grid.type"] = 0;
        if (runBgColor)     updateData["backgroundColor"] = "#000000";
        if (runSharedFog)   updateData["fog.mode"] = 2; // Shared Exploration Modo V14
        if (runTokenVision) updateData["tokenVision"] = true;
        if (runGlobalLight) updateData["environment.globalLight.enabled"] = true;
        if (runBgVolume)    updateData["playlistSoundVolume"] = 0;

        dialog.close();

        // Processamento em lote
        let updatedCount = 0;
        ui.notifications.info("Iniciando processamento das atualizações de cena...");

        for (const id of selectedIds) {
          const scene = game.scenes.get(id);
          if (!scene) continue;
          try {
            await scene.update(updateData);
            updatedCount++;
          } catch (err) {
            console.error(`Erro ao atualizar a cena [${scene.name}]:`, err);
          }
        }

        ui.notifications.info(`Sucesso! ${updatedCount} cena(s) foram atualizadas em lote.`);
      });
    },
    rejectClose: false
  });
})();

