  // ── Data helpers ───────────────────────────────────────────────────────────
  const DOC_TYPES = [
    { key:"Actor",        label:"Atores",    col: game.actors    },
    { key:"Item",         label:"Itens",     col: game.items     },
    { key:"JournalEntry", label:"Diários",   col: game.journal   },
    { key:"RollTable",    label:"Tabelas",   col: game.tables    },
    { key:"Macro",        label:"Macros",    col: game.macros    },
    { key:"Playlist",     label:"Playlists", col: game.playlists },
    { key:"Scene",        label:"Cenas",     col: game.scenes    },
    { key:"Cards",        label:"Cartas",    col: game.cards     },
  ];
  const OWN_LABELS = { 0:"Nenhum", 1:"Limitado", 2:"Observador", 3:"Proprietário" };

  function getCol(type) { return DOC_TYPES.find(t => t.key === type)?.col; }
  function ownLabel(lvl) { return OWN_LABELS[lvl] ?? "?"; }
  function currentOwn(doc, userId) {
    const own = doc.ownership ?? {};
    const lvl = userId === "default" ? (own.default ?? 0) : (own[userId] ?? own.default ?? 0);
    return ownLabel(lvl);
  }
  function allDocsInFolder(folder) {
    const col = getCol(folder.type);
    if (!col) return [];
    const direct = col.filter(d => d.folder?.id === folder.id);
    const subs   = game.folders.filter(f => f.folder?.id === folder.id);
    return [...direct, ...subs.flatMap(allDocsInFolder)];
  }
  function getSelectedDocs(selIds) {
    const docs = [];
    for (const id of selIds) {
      if (id.startsWith("docs:")) {
        const fid = id.slice(5); const folder = game.folders.get(fid);
        if (folder) { const col = getCol(folder.type); if (col) docs.push(...col.filter(d => d.folder?.id === fid)); }
      } else if (id.startsWith("orphan:")) {
        const type = id.slice(7); const col = getCol(type);
        if (col) docs.push(...col.filter(d => !d.folder));
      } else {
        const folder = game.folders.get(id);
        if (folder) docs.push(...allDocsInFolder(folder));
      }
    }
    return [...new Map(docs.map(d => [d.id, d])).values()];
  }

  // ── Tree HTML builder ──────────────────────────────────────────────────────
  function folderNodeHTML(folder, level) {
    const pad = level * 14 + 4;
    const col = DOC_TYPES.find(t => t.key === folder.type)?.col;
    const subs = game.folders.filter(f => f.folder?.id === folder.id);
    const docs = col ? col.filter(d => d.folder?.id === folder.id) : [];
    const hasChildren = subs.length > 0 || docs.length > 0;
    const childrenHTML = [
      ...subs.map(sf => folderNodeHTML(sf, level + 1)),
      docs.length > 0 ? `<div class="om-tree-row" style="padding-left:${pad + 18}px">
          <input type="checkbox" class="om-cb" data-nid="docs:${folder.id}">
          <i class="fa-regular fa-file om-di"></i>
          <span class="om-node-name">📄 ${docs.length} documentos</span>
        </div>` : ""
    ].join("");
    return `
      <div class="om-tree-row" style="padding-left:${pad}px">
        ${hasChildren ? `<span class="om-toggle" data-cid="fc-${folder.id}">▶</span>` : `<span style="width:12px;display:inline-block"></span>`}
        <input type="checkbox" class="om-cb" data-nid="${folder.id}">
        <i class="fa-solid fa-folder om-fi"></i>
        <span class="om-node-name">${folder.name}</span>
      </div>
      <div class="om-tree-children" id="fc-${folder.id}">${childrenHTML}</div>`;
  }

  function buildTreeHTML() {
    return DOC_TYPES.map(t => {
      const rootFolders = game.folders.filter(f => f.type === t.key && !f.folder);
      const orphans = t.col.filter(d => !d.folder);
      if (rootFolders.length === 0 && orphans.length === 0) return "";
      const childrenHTML = [
        ...rootFolders.map(f => folderNodeHTML(f, 1)),
        orphans.length > 0 ? `<div class="om-tree-row" style="padding-left:18px">
            <input type="checkbox" class="om-cb" data-nid="orphan:${t.key}">
            <i class="fa-regular fa-file om-di"></i>
            <span class="om-node-name">📄 Sem Pasta (${orphans.length})</span>
          </div>` : ""
      ].join("");
      return `
        <div class="om-type-hdr" data-cid="tc-${t.key}">
          <span class="om-toggle">▶</span>
          <span class="om-type-label">${t.label}</span>
        </div>
        <div class="om-tree-children" id="tc-${t.key}">${childrenHTML}</div>`;
    }).join("");
  }

  // ── Content ────────────────────────────────────────────────────────────────
  const usersHTML = `<option value="default">Padrão (Default)</option>` +
    game.users.contents.map(u => `<option value="${u.id}">${u.name}${u.isGM ? " (GM)" : ""}</option>`).join("");
  const levelsHTML = Object.entries(OWN_LABELS).map(([v, l]) => `<option value="${v}">${l}</option>`).join("");

  const content = `<div id="om-root">
    <div class="om-hdr"><h2>🔑 Gerenciador de Ownership</h2><p>Selecione pastas ou documentos e aplique ownership em massa.</p></div>
    <div class="om-main">
      <div class="om-left">
        <div class="om-toolbar">
          <button type="button" class="om-btn-sm" id="om-sel-all">✔ Todos</button>
          <button type="button" class="om-btn-sm" id="om-sel-none">✘ Limpar</button>
          <input type="text" class="om-search" id="om-search" placeholder="🔍 Buscar...">
          <span class="om-sel-count" id="om-count">0 sel.</span>
        </div>
        <div class="om-tree" id="om-tree">${buildTreeHTML()}</div>
      </div>
      <div class="om-right">
        <div class="om-cfg"><label class="om-lbl">Usuário</label><select class="om-sel" id="om-user">${usersHTML}</select></div>
        <div class="om-cfg"><label class="om-lbl">Nível de Ownership</label><select class="om-sel" id="om-level">${levelsHTML}</select></div>
        <div class="om-preview"><div class="om-prev-title">Preview</div><div id="om-prev-content">Selecione documentos...</div></div>
        <button type="button" class="om-apply" id="om-apply">✓ Aplicar Ownership</button>
      </div>
    </div>
    <div class="om-footer"><button type="button" class="om-close-btn" id="om-close">✖ Fechar</button></div>
  </div>`;

  // ── Dialog ─────────────────────────────────────────────────────────────────
  await foundry.applications.api.DialogV2.wait({
    window: { title: "Gerenciador de Ownership", id: "jsd-ownership-manager", resizable: true },
    position: { width: 760, height: 560 },
    content,
    buttons: [{ action: "noop", label: "–", callback: () => null }],

    render: (_event, dialog) => {
      const el = dialog.element;
      const wc = el.querySelector(".window-content");
      if (wc) { wc.style.setProperty("padding","0","important"); wc.style.setProperty("overflow","hidden","important"); }

      // Size management
      requestAnimationFrame(() => {
        const root = el.querySelector("#om-root");
        if (!root) return;
        function applyH() {
          const c = el.querySelector(".window-content");
          const h = el.querySelector(".window-header");
          if (!c || !root) return;
          const avail = window.innerHeight - 40 - (h?.offsetHeight ?? 40);
          c.style.setProperty("height", `${Math.max(400, avail)}px`, "important");
          c.style.setProperty("overflow-y", "hidden", "important");
        }
        applyH();
        new ResizeObserver(applyH).observe(root);
      });

      // State
      const selIds = new Set();

      function updateCount() {
        const cnt = el.querySelector("#om-count");
        if (cnt) cnt.textContent = `${selIds.size} sel.`;
      }
      function updatePreview() {
        const docs   = getSelectedDocs(selIds);
        const userId = el.querySelector("#om-user")?.value ?? "default";
        const lvl    = parseInt(el.querySelector("#om-level")?.value ?? "0");
        const label  = ownLabel(lvl);
        const uname  = userId === "default" ? "Padrão" : (game.users.get(userId)?.name ?? "?");
        let html = `<strong>${docs.length} documento(s) serão modificados</strong><br>
          ${uname} → <span class="om-badge om-l${lvl}">${label}</span>`;
        if (docs.length > 0) {
          html += `<ul class="om-prev-list">` +
            docs.slice(0, 8).map(d => `<li>${d.name} <span class="om-cur-own">(${currentOwn(d, userId)})</span></li>`).join("") +
            (docs.length > 8 ? `<li>... e mais ${docs.length - 8}</li>` : "") +
            `</ul>`;
        }
        const pc = el.querySelector("#om-prev-content");
        if (pc) pc.innerHTML = html;
      }

      // Tree toggles (type headers)
      el.querySelectorAll(".om-type-hdr").forEach(hdr => {
        hdr.addEventListener("click", () => {
          const cid = hdr.dataset.cid;
          const children = el.querySelector(`#${cid}`);
          if (!children) return;
          const toggle = hdr.querySelector(".om-toggle");
          const open = children.classList.toggle("open");
          if (toggle) toggle.textContent = open ? "▼" : "▶";
        });
      });

      // Inline folder toggles
      el.addEventListener("click", (e) => {
        const tog = e.target.closest(".om-toggle[data-cid]");
        if (!tog) return;
        const children = el.querySelector(`#${tog.dataset.cid}`);
        if (!children) return;
        const open = children.classList.toggle("open");
        tog.textContent = open ? "▼" : "▶";
      });

      // Checkboxes
      el.addEventListener("change", (e) => {
        const cb = e.target.closest(".om-cb");
        if (!cb) return;
        const nid = cb.dataset.nid;
        if (cb.checked) selIds.add(nid); else selIds.delete(nid);
        updateCount(); updatePreview();
      });

      el.querySelector("#om-sel-all")?.addEventListener("click", () => {
        el.querySelectorAll(".om-cb").forEach(cb => { cb.checked = true; selIds.add(cb.dataset.nid); });
        updateCount(); updatePreview();
      });
      el.querySelector("#om-sel-none")?.addEventListener("click", () => {
        el.querySelectorAll(".om-cb").forEach(cb => { cb.checked = false; });
        selIds.clear(); updateCount(); updatePreview();
      });

      // Search
      el.querySelector("#om-search")?.addEventListener("input", (e) => {
        const term = e.target.value.toLowerCase();
        el.querySelectorAll(".om-tree-row").forEach(row => {
          const name = row.querySelector(".om-node-name")?.textContent.toLowerCase() ?? "";
          row.style.display = !term || name.includes(term) ? "" : "none";
        });
      });

      el.querySelector("#om-user")?.addEventListener("change", updatePreview);
      el.querySelector("#om-level")?.addEventListener("change", updatePreview);

      // Apply
      el.querySelector("#om-apply")?.addEventListener("click", async () => {
        const docs   = getSelectedDocs(selIds);
        if (docs.length === 0) { ui.notifications.warn("Nenhum documento selecionado."); return; }
        const userId = el.querySelector("#om-user")?.value ?? "default";
        const lvl    = parseInt(el.querySelector("#om-level")?.value ?? "0");
        const uname  = userId === "default" ? "Padrão" : (game.users.get(userId)?.name ?? "?");

        const confirmed = await foundry.applications.api.DialogV2.wait({
          window: { title: "Confirmar Ownership" },
          content: `<p>Irá modificar <strong>${docs.length} documento(s)</strong>.<br>
                    Usuário: <strong>${uname}</strong> → <strong>${ownLabel(lvl)}</strong>.<br>
                    Esta ação não pode ser desfeita facilmente.</p>`,
          buttons: [
            { action:"yes", label:"Confirmar", icon:"fas fa-check", default:true, callback:()=>true  },
            { action:"no",  label:"Cancelar",  icon:"fas fa-times",              callback:()=>false },
          ],
          rejectClose: false,
        });
        if (!confirmed) return;

        let ok = 0, err = 0;
        ui.notifications.info(`Aplicando ownership a ${docs.length} documento(s)...`);
        for (const doc of docs) {
          try {
            const own = foundry.utils.duplicate(doc.ownership ?? {});
            if (userId === "default") own.default = lvl; else own[userId] = lvl;
            await doc.update({ ownership: own });
            ok++;
          } catch(e) { console.error("[JSD-OM]", doc.name, e); err++; }
        }
        if (err === 0) ui.notifications.info(`✓ Ownership aplicada em ${ok} documento(s).`);
        else           ui.notifications.warn(`Aplicado em ${ok}, ${err} falharam.`);

        selIds.clear();
        el.querySelectorAll(".om-cb").forEach(cb => { cb.checked = false; });
        updateCount(); updatePreview();
      });

      el.querySelector("#om-close")?.addEventListener("click", () => dialog.close({ animate: false }));
    },
    rejectClose: false,
  });
})();

