// ── Helpers ───────────────────────────────────────────────────────────────────

async function fogReset() {
  await canvas.fog.reset();
  ui.notifications.info("Fog of War reset.");
}

async function fogToggle() {
  const current = canvas.scene.tokenVision;
  await canvas.scene.update({ tokenVision: !current });
  ui.notifications.info(`Token Vision: ${!current ? "ON" : "OFF"}`);
}

// ─── Door Helpers ─────────────────────────────────────────────

function getTargetWalls(onlySelected) {
  if (onlySelected) {
    const sel = canvas.walls.controlled;
    if (!sel.length) {
      ui.notifications.warn("No walls selected! Select doors on the canvas first.");
      return null;
    }
    return sel.map(w => w.document);
  }
  return canvas.scene.walls.contents;
}

function isDoor(wallDoc) {
  return wallDoc.door === CONST.WALL_DOOR_TYPES.DOOR ||
         wallDoc.door === CONST.WALL_DOOR_TYPES.SECRET;
}

async function doorAction(action, onlySelected) {
  const walls = getTargetWalls(onlySelected);
  if (!walls) return;

  const doors = walls.filter(w => isDoor(w));
  if (!doors.length) {
    ui.notifications.warn("No doors found in the target selection.");
    return;
  }

  let updates = [];
  switch (action) {
    case "open":
      updates = doors.map(w => ({ _id: w.id, ds: CONST.WALL_DOOR_STATES.OPEN }));
      break;
    case "close":
      updates = doors.map(w => ({ _id: w.id, ds: CONST.WALL_DOOR_STATES.CLOSED }));
      break;
    case "lock":
      // Toggle: LOCKED → CLOSED, anything else → LOCKED
      updates = doors.map(w => ({
        _id: w.id,
        ds: w.ds === CONST.WALL_DOOR_STATES.LOCKED
          ? CONST.WALL_DOOR_STATES.CLOSED
          : CONST.WALL_DOOR_STATES.LOCKED
      }));
      break;
    case "secret":
      // Toggle between DOOR and SECRET type
      updates = doors.map(w => ({
        _id: w.id,
        door: w.door === CONST.WALL_DOOR_TYPES.SECRET
          ? CONST.WALL_DOOR_TYPES.DOOR
          : CONST.WALL_DOOR_TYPES.SECRET
      }));
      break;
  }

  await canvas.scene.updateEmbeddedDocuments("Wall", updates);

  const scope  = onlySelected ? "selected" : "all";
  const labels = { open: "Opened", close: "Closed", lock: "Lock-toggled", secret: "Toggled Secret type on" };
  ui.notifications.info(`${labels[action]} ${doors.length} door(s) [${scope}].`);
}

// ─── Mass Edit Helper ─────────────────────────────────────────

function openMassEdit(onlySelected) {
  const mod = game.modules.get("multi-token-edit");
  if (!mod?.active) {
    ui.notifications.error("Baileywiki Mass Edit module is not active!");
    return;
  }

  // Switch to Walls layer if not already there
  if (!(canvas.activeLayer instanceof WallsLayer)) {
    canvas.walls.activate();
  }

  // Select target doors
  if (!onlySelected) {
    canvas.walls.releaseAll();
    const doorPlaceables = canvas.walls.placeables.filter(w =>
      w.document.door === CONST.WALL_DOOR_TYPES.DOOR ||
      w.document.door === CONST.WALL_DOOR_TYPES.SECRET
    );
    doorPlaceables.forEach(w => w.control({ releaseOthers: false }));
  }

  if (!canvas.walls.controlled.length) {
    ui.notifications.warn("No doors selected for Mass Edit.");
    return;
  }

  // Try known Mass Edit API entry points
  const api = mod.api ?? globalThis.MassEdit ?? globalThis["multi-token-edit"];

  if (api?.showMassConfig) {
    api.showMassConfig(canvas.walls.controlled);
    return;
  }
  if (api?.openMassEdit) {
    api.openMassEdit(canvas.walls.controlled);
    return;
  }

  // Fallback: simulate Shift+E keybind (the standard Mass Edit trigger)
  const event = new KeyboardEvent("keydown", {
    key: "e", code: "KeyE", shiftKey: true, bubbles: true, cancelable: true
  });
  document.dispatchEvent(event);
  ui.notifications.info("Mass Edit opened via Shift+E — walls are pre-selected.");
}

// ─── Select doors by filter ──────────────────────────────────

function selectDoorsByFilter(filter) {
  // Activate walls layer if needed
  if (!(canvas.activeLayer instanceof WallsLayer)) {
    canvas.walls.activate();
  }

  const DS = CONST.WALL_DOOR_STATES;
  const DT = CONST.WALL_DOOR_TYPES;

  const targets = canvas.walls.placeables.filter(w => {
    const doc = w.document;
    if (doc.door === 0) return false; // not a door
    switch (filter) {
      case "open":   return doc.ds === DS.OPEN;
      case "closed": return doc.ds === DS.CLOSED && doc.door !== DT.SECRET;
      case "locked": return doc.ds === DS.LOCKED;
      case "secret": return doc.door === DT.SECRET;
      default:       return false;
    }
  });

  canvas.walls.releaseAll();
  targets.forEach(w => w.control({ releaseOthers: false }));

  return targets.length;
}

// ─── Status ───────────────────────────────────────────────────

function getStatus() {
  const walls   = canvas.scene.walls.contents;
  const doors   = walls.filter(w => w.door > 0);
  const open    = doors.filter(w => w.ds === CONST.WALL_DOOR_STATES.OPEN).length;
  const closed  = doors.filter(w => w.ds === CONST.WALL_DOOR_STATES.CLOSED).length;
  const locked  = doors.filter(w => w.ds === CONST.WALL_DOOR_STATES.LOCKED).length;
  const secret  = doors.filter(w => w.door === CONST.WALL_DOOR_TYPES.SECRET).length;
  const sel     = canvas.walls.controlled.filter(w => w.document.door > 0).length;
  const vis     = canvas.scene.tokenVision;
  return { total: doors.length, open, closed, locked, secret, sel, vis };
}

