// ── Dialog ────────────────────────────────────────────────────────────────────
await foundry.applications.api.DialogV2.wait({
  window:   { title: "🏰 Scene & Door Control", id: _SDC_ID, resizable: true },
  content:  buildHTML(getStatus()),
  buttons:  [{ action: "noop", label: "–", callback: () => null }],

  render: (_event, dialog) => {
    const el = dialog.element;

    // Adjust size
    dialog.setPosition({ width: 460, height: 580 });

    // Hide native footer
    el.querySelector(".form-footer")?.style.setProperty("display", "none", "important");
    const wc = el.querySelector(".window-content");
    if (wc) {
      wc.style.setProperty("padding", "0", "important");
      wc.style.setProperty("overflow", "hidden", "important");
    }

    // Fit root height to content area
    requestAnimationFrame(() => {
      function applyH() {
        const content = el.querySelector(".window-content");
        const root    = el.querySelector("#sdc-root");
        if (!content || !root) return;
        root.style.setProperty("height", content.clientHeight + "px", "important");
      }
      applyH();
      new ResizeObserver(applyH).observe(el);
    });

    let onlySelected = false;

    // ── Refresh status bar ─────────────────────────────────────────────────
    function refresh() {
      const st = getStatus();
      const bar = el.querySelector("#sdc-status-bar");
      if (bar) bar.innerHTML = `
        <span class="sdc-pill pill-total" title="All doors">🚪 Total: ${st.total}</span>
        <span class="sdc-pill pill-open   pill-clickable" data-filter="open"   title="Click to select Open">🟢 Open: ${st.open}</span>
        <span class="sdc-pill pill-closed pill-clickable" data-filter="closed" title="Click to select Closed">🟡 Closed: ${st.closed}</span>
        <span class="sdc-pill pill-locked pill-clickable" data-filter="locked" title="Click to select Locked">🔴 Locked: ${st.locked}</span>
        <span class="sdc-pill pill-secret pill-clickable" data-filter="secret" title="Click to select Secret">🔵 Secret: ${st.secret}</span>
        <span class="sdc-pill pill-sel" title="Selected doors">✨ Selected: ${st.sel}</span>`;
      const ftog = el.querySelector("#sdc-fog-toggle");
      if (ftog) ftog.innerHTML = `<span class="btn-icon">${st.vis ? "🟢" : "⭕"}</span>Token Vision: ${st.vis ? "ON" : "OFF"}`;
    }

    // ── Scope ─────────────────────────────────────────────────────────────
    el.querySelector("#sdc-scope-all")?.addEventListener("click", () => {
      onlySelected = false;
      el.querySelector("#sdc-scope-all").classList.add("active");
      el.querySelector("#sdc-scope-sel").classList.remove("active");
    });
    el.querySelector("#sdc-scope-sel")?.addEventListener("click", () => {
      onlySelected = true;
      el.querySelector("#sdc-scope-sel").classList.add("active");
      el.querySelector("#sdc-scope-all").classList.remove("active");
    });

    // ── Status pill → select by filter (event delegation) ─────────────────
    el.querySelector("#sdc-status-bar")?.addEventListener("click", (e) => {
      const pill = e.target.closest(".pill-clickable");
      if (!pill) return;
      const filter = pill.dataset.filter;
      const count  = selectDoorsByFilter(filter);
      if (count === 0) { ui.notifications.warn(`No ${filter} doors found.`); return; }
      onlySelected = true;
      el.querySelector("#sdc-scope-sel").classList.add("active");
      el.querySelector("#sdc-scope-all").classList.remove("active");
      refresh();
      ui.notifications.info(`Selected ${count} ${filter} door(s) — scope set to Selected Only.`);
    });

    // ── Fog ───────────────────────────────────────────────────────────────
    el.querySelector("#sdc-fog-reset")?.addEventListener("click",  async () => { await fogReset(); });
    el.querySelector("#sdc-fog-toggle")?.addEventListener("click", async () => { await fogToggle(); refresh(); });

    // ── Doors ─────────────────────────────────────────────────────────────
    el.querySelector("#sdc-door-open"  )?.addEventListener("click", async () => { await doorAction("open",   onlySelected); refresh(); });
    el.querySelector("#sdc-door-close" )?.addEventListener("click", async () => { await doorAction("close",  onlySelected); refresh(); });
