// ─── Helpers ──────────────────────────────────────────────────────────────────

function parseFactor(str) {
  str = (str ?? "").trim();
  if (!str) return NaN;
  const frac = str.match(/^(\d+(?:\.\d+)?)\s*\/\s*(\d+(?:\.\d+)?)$/);
  if (frac) { const d = parseFloat(frac[2]); return d === 0 ? NaN : parseFloat(frac[1]) / d; }
  const pct = str.match(/^(\d+(?:\.\d+)?)\s*%$/);
  if (pct) return parseFloat(pct[1]) / 100;
  const n = parseFloat(str);
  return isNaN(n) ? NaN : n;
}

const PRESETS = [
  { label: "25%",               val: 0.25 },
  { label: "1/3 (~33.3%)",     val: 1/3  },
  { label: "50%",               val: 0.5  },
  { label: "75%",               val: 0.75 },
  { label: "100% (sem mudança)", val: 1   },
  { label: "125%",              val: 1.25 },
  { label: "150%",              val: 1.5  },
  { label: "200%",              val: 2    },
];
const presetOpts = PRESETS.map((p, i) =>
  `<option value="${p.val}" ${i === 2 ? "selected" : ""}>${p.label}</option>`
).join("");

const MIN_GRID = 20;
const MIN_ICON = 32;

// Computa o resultado de reescala de uma cena dado o fator
function sceneResult(scene, rF) {
  const rawG = scene.grid.size * rF;
  const gridOk = rawG >= MIN_GRID;
  const minFactor = gridOk ? rF : MIN_GRID / scene.grid.size;
  return {
    gridOk, rawG,
    newG: Math.max(MIN_GRID, Math.round(rawG)),
    newW: Math.round(scene.width  * rF),
    newH: Math.round(scene.height * rF),
    minFactor: parseFloat(minFactor.toFixed(8)),
    minW: Math.round(scene.width  * minFactor),
    minH: Math.round(scene.height * minFactor)
  };
}

// ─── Scene tree ───────────────────────────────────────────────────────────────

const activeId = canvas.scene?.id ?? "";
