function renderSceneRow(scene, depth) {
  const pl = depth * 14 + 18;
  const isActive = scene.id === activeId;
  return `<label class="sr4-scene-row${isActive ? " sr4-active" : ""}" data-scene-id="${scene.id}"
      style="padding-left:${pl}px">
    <input type="checkbox" class="sr4-scene-cb" value="${scene.id}"
      data-gsize="${scene.grid.size}" data-w="${scene.width}" data-h="${scene.height}"
      data-gdist="${scene.grid.distance}" data-gunits="${scene.grid.units || "ft"}"
      ${isActive ? "checked" : ""}>
    <span class="sr4-scene-name">${scene.name}${isActive ? " ●" : ""}</span>
    <span class="sr4-scene-dims">${scene.width}×${scene.height}px | g:${scene.grid.size} | d:${scene.grid.distance}</span>
  </label>`;
}

function renderFolderNode(folder, depth) {
  const childFolders = allFolders.filter(f => (f.folder?.id ?? null) === folder.id)
    .sort((a,b) => (a.sort??0)-(b.sort??0));
  const folderScenes = [...game.scenes]
    .filter(s => (s.folder?.id ?? null) === folder.id)
    .sort((a,b) => (a.sort??0)-(b.sort??0) || a.name.localeCompare(b.name));
  const pl = depth * 14;
  const hasChildren = childFolders.length > 0 || folderScenes.length > 0;
  return `<div class="sr4-folder-node" data-folder-id="${folder.id}">
    <div class="sr4-folder-header" style="padding-left:${pl}px">
      <span class="sr4-fold-toggle">${hasChildren ? "▼" : " "}</span>
      <input type="checkbox" class="sr4-folder-cb" data-folder-id="${folder.id}">
      <span class="sr4-folder-icon">📁</span>
      <span class="sr4-folder-name-text">${folder.name}</span>
    </div>
    <div class="sr4-folder-content">
      ${folderScenes.map(s => renderSceneRow(s, depth + 1)).join("")}
      ${childFolders.map(f => renderFolderNode(f, depth + 1)).join("")}
    </div>
  </div>`;
}

const rootFolders = allFolders.filter(f => !f.folder)
