        </div>
        <div class="sr4-row">
          <div class="sr4-field">
            <label>Novo Distance</label>
            <input type="number" id="sr4-new-dist" min="0.01" step="0.1" placeholder="vazio = manter" />
          </div>
        </div>
      </div>

      <!-- Backup -->
      <label class="sr4-check">
        <input type="checkbox" id="sr4-backup" checked>
        Criar backup no compendium "Scene Rescaler {data}" antes de aplicar
      </label>

      <!-- Pre-flight -->
      <div class="sr4-preflight" id="sr4-preflight"></div>

    </div>
  `,

  render: () => {
    // ── Constrain window-content height + ResizeObserver (LEARNINGS #002) ─
    // requestAnimationFrame só não basta: ao trocar de aba o conteúdo cresce e
    // os botões somem. ResizeObserver no elemento interno re-aplica o constraint.
    requestAnimationFrame(() => {
      const win     = document.querySelector("#sr4-root")?.closest(".window-app");
      const content = win?.querySelector(".window-content");
      const header  = win?.querySelector(".window-header");
      const footer  = win?.querySelector("footer, .window-footer, .form-footer");
      const inner   = document.querySelector("#sr4-root");
      if (!content || !inner) return;
      function applyH() {
        const avail = window.innerHeight - 40
          - (header?.offsetHeight ?? 40)
          - (footer?.offsetHeight ?? 54);
        content.style.setProperty("height", `${Math.max(200, avail)}px`, "important");
        content.style.setProperty("overflow-y", "auto", "important");
      }
      applyH();
      new ResizeObserver(applyH).observe(inner);
    });

    const multValEl = document.querySelector("#sr4-mult-val");
    const presetEl  = document.querySelector("#sr4-preset-val");
    const ladoPxEl  = document.querySelector("#sr4-lado-px");
    const newDistEl = document.querySelector("#sr4-new-dist");
    const backupEl  = document.querySelector("#sr4-backup");
    const pfEl      = document.querySelector("#sr4-preflight");
    const factorEl  = document.querySelector("#sr4-out-factor");
    const factPrev  = document.querySelector("#sr4-factor-preview");

    // ── Seleção em lote ──────────────────────────────────────────────
    document.querySelector("#sr4-sel-all").addEventListener("click", () => {
      document.querySelectorAll(".sr4-scene-cb:not([style*='display: none']),.sr4-scene-row:not([style*='display: none']) .sr4-scene-cb").forEach(cb => cb.checked = true);
      updateFolderStates(); update();
    });
    document.querySelector("#sr4-sel-none").addEventListener("click", () => {
      document.querySelectorAll(".sr4-scene-cb").forEach(cb => cb.checked = false);
      updateFolderStates(); update();
    });

    // ── Fold toggle (expandir/recolher pasta) ─────────────────────
    function wireToggle(toggle) {
      toggle.addEventListener("click", (e) => {
        e.preventDefault(); e.stopPropagation();
        const node    = toggle.closest(".sr4-folder-node");
        const content = node.querySelector(":scope > .sr4-folder-content");
        const isOpen  = content.style.display !== "none";
        content.style.display = isOpen ? "none" : "";
        toggle.classList.toggle("closed", isOpen);
      });
    }
    document.querySelectorAll(".sr4-fold-toggle").forEach(wireToggle);

    // ── Checkbox de pasta → cascata para filhos ────────────────────
    function wireFolderCb(fcb) {
      fcb.addEventListener("change", () => {
        const node = fcb.closest(".sr4-folder-node");
        node.querySelectorAll(".sr4-scene-cb").forEach(cb => { cb.checked = fcb.checked; });
        updateFolderStates(); update();
      });
      // Nome da pasta também alterna
      fcb.closest(".sr4-folder-header")?.querySelector(".sr4-folder-name-text")
        ?.addEventListener("click", () => { fcb.click(); });
    }
    document.querySelectorAll(".sr4-folder-cb").forEach(wireFolderCb);

    // ── Estado tri-state das pastas ────────────────────────────────
    function updateFolderStates() {
      // Processar do mais profundo para o topo
      const allNodes = [...document.querySelectorAll(".sr4-folder-node")].reverse();
      for (const node of allNodes) {
        const fcb   = node.querySelector(":scope > .sr4-folder-header > .sr4-folder-cb");
        const cbs   = [...node.querySelectorAll(".sr4-scene-cb")];
        if (!fcb || !cbs.length) continue;
        const n = cbs.filter(c => c.checked).length;
        fcb.checked       = n > 0;
        fcb.indeterminate = n > 0 && n < cbs.length;
      }
    }

    // ── Busca ──────────────────────────────────────────────────────
    const searchInput = document.querySelector("#sr4-search");
    searchInput.addEventListener("input", () => {
      const q = searchInput.value.toLowerCase().trim();

      if (!q) {
        // Restaura visibilidade de tudo
        document.querySelectorAll(".sr4-scene-row, .sr4-folder-node").forEach(el => {
          el.style.display = "";
        });
        // Restaura fold toggles (volta ao estado padrão: aberto)
        document.querySelectorAll(".sr4-folder-content").forEach(c => c.style.display = "");
        document.querySelectorAll(".sr4-fold-toggle").forEach(t => t.classList.remove("closed"));
        update(); return;
      }

      // Mostrar/ocultar rows de cena
      document.querySelectorAll(".sr4-scene-row").forEach(row => {
        const name = (row.querySelector(".sr4-scene-name")?.textContent ?? "").toLowerCase();
        row.style.display = name.includes(q) ? "" : "none";
      });

      // Mostrar pasta se tiver alguma cena visível; expandir automaticamente
      // Processar do mais profundo para o topo
      const allNodes = [...document.querySelectorAll(".sr4-folder-node")].reverse();
      for (const node of allNodes) {
        const hasVisible = [...node.querySelectorAll(".sr4-scene-row")]
          .some(r => r.style.display !== "none");
        node.style.display = hasVisible ? "" : "none";
        if (hasVisible) {
          const content = node.querySelector(":scope > .sr4-folder-content");
          const toggle  = node.querySelector(":scope > .sr4-folder-header > .sr4-fold-toggle");
          if (content) content.style.display = "";
          if (toggle)  toggle.classList.remove("closed");
        }
      }
      update();
    });

    document.querySelectorAll("input[name=scaleMode]").forEach(r => {
      r.addEventListener("change", () => {
        document.querySelectorAll(".sr4-mode-panel").forEach(p => p.classList.remove("active"));
        document.querySelector(`#sr4-panel-${r.value}`).classList.add("active");
        factPrev.style.display = r.value === "lado" ? "none" : "";
        update();
      });
    });

    function getMode() { return document.querySelector("input[name=scaleMode]:checked")?.value ?? "mult"; }

    function getGlobalRF() {
      const mode = getMode();
      if (mode === "mult")   return parseFactor(multValEl.value);
      if (mode === "preset") return parseFloat(presetEl.value);
      return NaN; // lado: per-scene
    }

    function getPerSceneRF(scene) {
      const mode = getMode();
      if (mode === "lado") {
        const maxPx = parseFloat(ladoPxEl.value);
        const ref   = document.querySelector("input[name=ladoRef]:checked")?.value ?? "w";
        const base  = ref === "w" ? scene.width : scene.height;
        return (!maxPx || !base) ? NaN : maxPx / base;
      }
      return getGlobalRF();
    }

    function update() {
      const mode  = getMode();
      const rF    = getGlobalRF();
      const newDist = newDistEl.value ? parseFloat(newDistEl.value) : null;

      // Factor preview (only for mult/preset)
      if (mode !== "lado") {
        if (!isNaN(rF) && rF > 0 && rF !== 1) {
          factorEl.textContent = `${rF.toFixed(6)}×`; factorEl.classList.remove("err");
        } else if (rF === 1 || !multValEl.value) {
          factorEl.textContent = "1× (sem mudança)"; factorEl.classList.remove("err");
        } else {
          factorEl.textContent = "✖ inválido"; factorEl.classList.add("err");
        }
      }

      // Pre-flight summary
      const selectedCbs = [...document.querySelectorAll(".sr4-scene-cb:checked")];
      if (!selectedCbs.length) {
        pfEl.classList.remove("visible"); pfEl.innerHTML = ""; return;
      }

      const items = [];
      let nGridErrors = 0, nTotal = 0;

      for (const cb of selectedCbs) {
        const scene = game.scenes.get(cb.value);
        if (!scene) continue;
        const rf = mode === "lado" ? (() => {
          const maxPx = parseFloat(ladoPxEl.value);
          const ref   = document.querySelector("input[name=ladoRef]:checked")?.value ?? "w";
          const base  = ref === "w" ? scene.width : scene.height;
          return (!maxPx || !base) ? NaN : maxPx / base;
        })() : rF;

        nTotal++;
        if (!isNaN(rf) && rf > 0 && rf !== 1) {
          const res = sceneResult(scene, rf);
          if (!res.gridOk) nGridErrors++;
        } else if (isNaN(rf) || rf <= 0) {
          nGridErrors++; // sinaliza problema
        }
      }

      if (nTotal === 0) { pfEl.classList.remove("visible"); return; }

      items.push({ t:"info", m:`ℹ ${nTotal} cena(s) selecionada(s). Revisão detalhada no próximo passo.` });
      if (nGridErrors > 0)
        items.push({ t:"warn", m:`⚠ ${nGridErrors} cena(s) com grid.size < ${MIN_GRID}px: será oferecida opção de fator mínimo na confirmação.` });
      if (newDist !== null && newDist > 0)
        items.push({ t:"info", m:`ℹ Grid.distance → ${newDist} aplicado a todas.` });
      if (!backupEl.checked)
        items.push({ t:"warn", m:"⚠ Backup desativado." });

      pfEl.innerHTML = items.map(i => `<div class="sr4-pf-item ${i.t}">${i.m}</div>`).join("");
      pfEl.classList.add("visible");
    }

    document.querySelectorAll(".sr4-scene-cb").forEach(cb => cb.addEventListener("change", () => {
      updateFolderStates(); update();
    }));
    multValEl.addEventListener("input", update);
    presetEl.addEventListener("change", update);
    ladoPxEl.addEventListener("input", update);
    document.querySelectorAll("input[name=ladoRef]").forEach(r => r.addEventListener("change", update));
    newDistEl.addEventListener("input", update);
    backupEl.addEventListener("change", update);
    update();
  },

  buttons: [
    {
      label: "Continuar →",
      action: "next",
      icon:   "fas fa-arrow-right",
      callback: (_evt, button) => {
        const form = button.closest("form");
        const mode = form.querySelector("input[name=scaleMode]:checked")?.value;
        const selectedIds = [...form.querySelectorAll(".sr4-scene-cb:checked")].map(cb => cb.value);
        const rF_global = (() => {
          if (mode === "mult")   return parseFactor(form.querySelector("#sr4-mult-val").value);
          if (mode === "preset") return parseFloat(form.querySelector("#sr4-preset-val").value);
          return NaN;
        })();
        const maxPx = parseFloat(form.querySelector("#sr4-lado-px")?.value ?? "0");
        const ladoRef = form.querySelector("input[name=ladoRef]:checked")?.value ?? "w";
        const newDistRaw = form.querySelector("#sr4-new-dist").value;
        return {
          selectedIds,
          mode,
          rF_global,
          maxPx,
          ladoRef,
          newDist:  newDistRaw ? parseFloat(newDistRaw) : null,
          doBackup: form.querySelector("#sr4-backup").checked
        };
      }
    },
    { label: "Cancelar", action: "cancel", icon: "fas fa-times" }
  ],
  rejectClose: false
});

if (!cfg) return;
const { selectedIds, mode, rF_global, maxPx, ladoRef, newDist, doBackup } = cfg;

if (!selectedIds.length) { ui.notifications.warn("Nenhuma cena selecionada."); return; }

// ─── Fator por cena ───────────────────────────────────────────────────────────

function getEffectiveRF(scene) {
  if (mode === "lado") {
    const base = ladoRef === "w" ? scene.width : scene.height;
    return (!maxPx || !base) ? NaN : maxPx / base;
  }
  return rF_global;
}

// ─── Resultados por cena ──────────────────────────────────────────────────────

const perScene = selectedIds.map(id => {
  const scene = game.scenes.get(id);
  if (!scene) return null;
  const rF = getEffectiveRF(scene);
  const res = !isNaN(rF) && rF > 0 ? sceneResult(scene, rF) : null;
  return { scene, rF, res };
}).filter(Boolean);

if (!perScene.length) { ui.notifications.warn("Cenas não encontradas."); return; }

// ─── Dialog de confirmação por cena ──────────────────────────────────────────

const rowsHTML = perScene.map(({ scene, rF, res }) => {
  const gs = scene.grid.size;
  const oldDist = scene.grid.distance;
  const dScale = (newDist !== null && newDist !== oldDist) ? (newDist / oldDist) : 1;
  const distStr = dScale !== 1 ? ` | dist: ${oldDist}→${newDist}` : "";

  // Fator inválido
  if (isNaN(rF) || rF <= 0 || !res) {
    return `<tr><td colspan="4" style="padding:4px">
      <div style="background:#2a1010;border:1px solid #6a1010;border-radius:4px;padding:6px 10px;margin:2px 0">
        <span style="color:#e84030">✖ ${scene.name} — fator inválido, será excluída.</span>
      </div></td></tr>`;
  }

  // Grid OK
  if (res.gridOk) {
    return `<tr style="border-bottom:1px solid #2a2018">
      <td style="text-align:center;padding:4px">
        <input type="checkbox" class="sr4-include" data-id="${scene.id}"
          data-rf="${rF}" checked style="accent-color:#d4a574;cursor:pointer">
      </td>
      <td style="color:#e8d5c0;padding:4px 8px;font-size:12px">${scene.name}</td>
      <td style="color:#e8d5c0;padding:4px 8px;font-size:11px">
        ${scene.width}×${scene.height} → ${res.newW}×${res.newH}
        <span style="color:#6a5a4a">(${(rF*100).toFixed(1)}%)${distStr}</span>
      </td>
      <td style="color:#90ffd8;padding:4px 8px;font-size:11px">${gs} → ${res.newG}px ✓</td>
    </tr>`;
  }

  // Grid ERRO — oferecer mínimo
  return `<tr><td colspan="4" style="padding:4px">
    <div class="sr4-grid-error" data-id="${scene.id}" data-min-factor="${res.minFactor}"
      style="background:#2a1010;border:1px solid #6a1010;border-radius:4px;padding:8px 10px;margin:2px 0">
      <div style="color:#e84030;font-weight:bold;margin-bottom:4px">⚠ ${scene.name}</div>
      <div style="color:#e8d5c0;font-size:11px;margin-bottom:6px">
        grid.size calculado com fator ${rF.toFixed(4)}×: <b>${res.rawG.toFixed(2)}px</b>
        (mínimo obrigatório: ${MIN_GRID}px) — fator não aplicável diretamente.
      </div>
      <div style="color:#c9a876;font-size:10px;margin-bottom:6px">
        Fator mínimo possível: <b style="color:#d4a574">${res.minFactor.toFixed(6)}×</b>
        — mantém grid.size = ${MIN_GRID}px
      </div>
      <label style="display:flex;align-items:flex-start;gap:6px;margin-bottom:5px;cursor:pointer;font-size:11px;color:#e8d5c0">
        <input type="radio" name="choice-${scene.id}" value="adjust" checked
          style="accent-color:#d4a574;margin-top:2px;flex-shrink:0">
        <span>
          Usar fator mínimo <b style="color:#d4a574">${res.minFactor.toFixed(6)}×</b>
          → ${res.minW}×${res.minH}
          | grid: ${gs} → ${MIN_GRID}px
          ${distStr}
        </span>
      </label>
      <label style="display:flex;align-items:flex-start;gap:6px;cursor:pointer;font-size:11px;color:#c9a876">
        <input type="radio" name="choice-${scene.id}" value="skip"
          style="accent-color:#d4a574;margin-top:2px;flex-shrink:0">
        <span>Excluir esta cena do batch</span>
      </label>
    </div>
  </td></tr>`;
}).join("");

const decisions = await foundry.applications.api.DialogV2.wait({
  window: { title: `Confirmar — ${perScene.length} cena(s)` },
  position: {
    width: 600,
    top:  Math.max(20, Math.round((window.innerHeight - 560) / 2)),
    left: Math.max(20, Math.round((window.innerWidth  - 600) / 2))
  },
  content: `
    <div style="font-family:var(--font-primary);color:#f5e6d3;padding:4px 2px;font-size:12px">
      <p style="color:#c9a876;font-size:11px;text-transform:uppercase;letter-spacing:.5px;margin:0 0 8px">
        Revisão por cena — desmarque as que não deseja alterar
      </p>
      <div style="max-height:380px;overflow-y:auto">
        <table style="width:100%;border-collapse:collapse">
          <thead>
            <tr style="border-bottom:1px solid #4a3a28">
              <th style="width:28px;padding:4px;color:#c9a876;font-size:10px"></th>
              <th style="padding:4px 8px;color:#c9a876;font-size:10px;text-align:left">Cena</th>
              <th style="padding:4px 8px;color:#c9a876;font-size:10px;text-align:left">Dimensões | Fator</th>
              <th style="padding:4px 8px;color:#c9a876;font-size:10px;text-align:left">Grid.size</th>
            </tr>
          </thead>
          <tbody>${rowsHTML}</tbody>
        </table>
      </div>
      ${doBackup ? `
        <p style="margin:8px 0 0;font-size:11px;color:#90ffd8;background:#1a2a1a;padding:5px 8px;border-radius:4px">
          ✓ Backup de todas as cenas aprovadas no compendium "Scene Rescaler {data}"
        </p>` : ""}
    </div>
  `,
  buttons: [
    {
      label: "Aplicar",
      action: "apply",
      icon: "fas fa-check",
      callback: (_evt, button) => {
        const form = button.closest("form");
        const approved = [];

        // Cenas OK (checkbox)
        form.querySelectorAll(".sr4-include:checked").forEach(cb => {
          approved.push({ id: cb.dataset.id, effectiveRF: parseFloat(cb.dataset.rf) });
        });

        // Cenas com erro de grid (radio)
        form.querySelectorAll(".sr4-grid-error").forEach(el => {
          const id = el.dataset.id;
          const choice = form.querySelector(`input[name="choice-${id}"]:checked`)?.value;
          if (choice === "adjust") {
            approved.push({ id, effectiveRF: parseFloat(el.dataset.minFactor) });
          }
          // "skip" → não adiciona
        });

        return approved.length ? approved : null;
      }
    },
    { label: "Cancelar", action: "cancel", icon: "fas fa-times" }
  ],
  rejectClose: false
});

if (!decisions?.length) { ui.notifications.info("Nenhuma cena aprovada."); return; }

// ─── Backup no Compendium (todas de uma vez, antes de alterar qualquer coisa) ─

if (doBackup) {
  ui.notifications.info("Criando backup no compendium...");
  try {
    const FOLDER_NAME = "Scene Rescaler Folder";
    let bkFolder = game.folders.find(f => f.name === FOLDER_NAME && f.type === "Compendium");
    if (!bkFolder) bkFolder = await Folder.create({ name: FOLDER_NAME, type: "Compendium" });

    const now  = new Date();
    const d    = now.toISOString().slice(0, 10);
    const h    = String(now.getHours()).padStart(2, "0");
    const m    = String(now.getMinutes()).padStart(2, "0");
    const packLabel = `Scene Rescaler ${d} ${h}h${m}`;
    const packName  = `scene-rescaler-${d}-${h}${m}`;

    const pack = await CompendiumCollection.createCompendium({ name: packName, label: packLabel, type: "Scene" });
    await pack.setFolder(bkFolder);

    for (const { id } of decisions) {
      const s = game.scenes.get(id);
      if (s) await pack.importDocument(s);
    }
    ui.notifications.info(`Backup: "${packLabel}" (${decisions.length} cena(s))`);
  } catch (err) {
    console.error("Scene Rescaler | Falha no backup:", err);
    const abort = await foundry.applications.api.DialogV2.wait({
      window: { title: "Falha no Backup" },
      position: { width: 360, top: 200, left: Math.max(20, Math.round((window.innerWidth-360)/2)) },
      content: `<div style="font-family:var(--font-primary);color:#f5e6d3;padding:4px;font-size:12px">
        <p style="color:#e84030">✖ Falha ao criar backup no compendium.</p>
        <p>Deseja prosseguir sem backup?</p></div>`,
      buttons: [
        { label: "Prosseguir sem backup", action: "ok",     icon: "fas fa-exclamation-triangle" },
        { label: "Cancelar",              action: "cancel", icon: "fas fa-times" }
      ],
      rejectClose: false
    });
    if (abort !== "ok") { ui.notifications.warn("Operação cancelada."); return; }
  }
}

// ─── Processar cenas sequencialmente ─────────────────────────────────────────

let totalProcessed = 0, totalObjects = 0;
const errors = [];

for (const { id, effectiveRF } of decisions) {
  const scene = game.scenes.get(id);
  if (!scene) { errors.push(`${id}: não encontrada`); continue; }

  ui.notifications.info(`Processando: ${scene.name}...`);

  const rScale   = effectiveRF;
  const newW     = Math.round(scene.width  * rScale);
  const newH     = Math.round(scene.height * rScale);
  const newG     = Math.max(MIN_GRID, Math.round(scene.grid.size * rScale));
  const oldDist  = scene.grid.distance;
  const dScale   = (newDist !== null && newDist !== oldDist) ? newDist / oldDist : 1;

  const rpx = v => Math.round(v);
  const r1  = v => Math.round(v * 10) / 10;
  const upd = {};

  if (rScale !== 1) { upd.width = newW; upd.height = newH; upd["grid.size"] = newG; }
  if (dScale !== 1) upd["grid.distance"] = newDist;

  // Paredes
  if (rScale !== 1) {
    const a = [];
    for (const w of scene.walls) a.push({ _id: w.id, c: w.c.map(v => rpx(v * rScale)) });
    if (a.length) upd.walls = a;
  }

  // Tiles
  if (rScale !== 1) {
    const a = [];
    for (const t of scene.tiles)
      a.push({ _id: t.id, x: rpx(t.x*rScale), y: rpx(t.y*rScale),
               width: rpx(t.width*rScale), height: rpx(t.height*rScale) });
    if (a.length) upd.tiles = a;
  }

  // Tokens — atômico: bypassa sistema de movimento
  {
    const a = [];
    for (const t of scene.tokens) {
      const u = { _id: t.id }; let ch = false;
      if (rScale !== 1) { u.x = rpx(t.x*rScale); u.y = rpx(t.y*rScale); ch = true; }
      if (dScale !== 1) {
        if (t.light.dim    !== 0) { u.light = { ...u.light, dim:    r1(t.light.dim    * dScale) }; ch = true; }
        if (t.light.bright !== 0) { u.light = { ...u.light, bright: r1(t.light.bright * dScale) }; ch = true; }
        if (t.sight.range   > 0)  { u.sight = { range: r1(t.sight.range * dScale) };               ch = true; }
        if (t.elevation    !== 0)  { u.elevation = r1(t.elevation * dScale);                        ch = true; }
      }
      if (ch) a.push(u);
    }
    if (a.length) upd.tokens = a;
  }

  // Luzes
  {
    const a = [];
    for (const l of scene.lights) {
      const u = { _id: l.id }; let ch = false;
      if (rScale !== 1) { u.x = rpx(l.x*rScale); u.y = rpx(l.y*rScale); ch = true; }
      if (dScale !== 1) {
        const cfg = {};
        if (l.config.dim    !== 0) { cfg.dim    = r1(l.config.dim    * dScale); ch = true; }
        if (l.config.bright !== 0) { cfg.bright = r1(l.config.bright * dScale); ch = true; }
        if (Object.keys(cfg).length) u.config = cfg;
        if (l.elevation !== 0) { u.elevation = r1(l.elevation * dScale); ch = true; }
      }
      if (ch) a.push(u);
    }
    if (a.length) upd.lights = a;
  }

  // Sons
  {
    const a = [];
    for (const s of scene.sounds) {
      const u = { _id: s.id }; let ch = false;
      if (rScale !== 1) { u.x = rpx(s.x*rScale); u.y = rpx(s.y*rScale); ch = true; }
      if (dScale !== 1) {
        if (s.radius    > 0)  { u.radius    = r1(s.radius    * dScale); ch = true; }
        if (s.elevation !== 0) { u.elevation = r1(s.elevation * dScale); ch = true; }
      }
      if (ch) a.push(u);
    }
    if (a.length) upd.sounds = a;
  }

  // Notas
  if (rScale !== 1) {
    const a = [];
    for (const n of scene.notes)
      a.push({ _id: n.id, x: rpx(n.x*rScale), y: rpx(n.y*rScale),
               iconSize: Math.max(MIN_ICON, rpx((n.iconSize ?? 40) * rScale)) });
    if (a.length) upd.notes = a;
  }

  // Drawings
  if (rScale !== 1) {
    const a = [];
    for (const d of scene.drawings) {
      const sh = d.shape ?? {}; const ns = { ...sh };
      if ("width"  in sh) ns.width  = rpx(sh.width  * rScale);
      if ("height" in sh) ns.height = rpx(sh.height * rScale);
      if (Array.isArray(sh.points) && sh.points.length) ns.points = sh.points.map(v => rpx(v*rScale));
      const u = { _id: d.id, x: rpx(d.x*rScale), y: rpx(d.y*rScale), shape: ns };
      if (d.strokeWidth) u.strokeWidth = Math.max(1, rpx(d.strokeWidth * rScale));
      if (d.fontSize)    u.fontSize    = Math.max(8, rpx(d.fontSize    * rScale));
      a.push(u);
    }
    if (a.length) upd.drawings = a;
  }

  // Regiões
  if (rScale !== 1) {
    const a = [];
    for (const r of scene.regions) {
      const shapes = (r.shapes ?? []).map(s => {
        const ns = { ...s };
        switch (s.type) {
          case "circle":
            ns.x = rpx(s.x*rScale); ns.y = rpx(s.y*rScale); ns.radius = rpx(s.radius*rScale); break;
          case "rectangle":
            ns.x = rpx(s.x*rScale); ns.y = rpx(s.y*rScale);
            ns.width = rpx(s.width*rScale); ns.height = rpx(s.height*rScale); break;
          case "ellipse":
            ns.x = rpx(s.x*rScale); ns.y = rpx(s.y*rScale);
            if ("radiusX" in s) ns.radiusX = rpx(s.radiusX*rScale);
            if ("radiusY" in s) ns.radiusY = rpx(s.radiusY*rScale); break;
          case "polygon":
            if (Array.isArray(s.points)) ns.points = s.points.map(v => rpx(v*rScale)); break;
        }
        return ns;
      });
      a.push({ _id: r.id, shapes });
    }
    if (a.length) upd.regions = a;
  }

  try {
    await scene.update(upd);
    totalProcessed++;
    totalObjects += ["walls","tiles","tokens","lights","sounds","notes","drawings","regions"]
      .reduce((acc, k) => acc + (upd[k]?.length ?? 0), 0);
  } catch (err) {
    console.error(`Scene Rescaler | Erro em "${scene.name}":`, err);
    errors.push(scene.name);
  }
}

// ─── Resultado ────────────────────────────────────────────────────────────────

const errStr = errors.length ? ` | ⚠ Falhas: ${errors.join(", ")}` : "";
ui.notifications.info(
  `Batch concluído: ${totalProcessed}/${decisions.length} cena(s) | ` +
  `${totalObjects} objetos atualizados${errStr}`
);

})();

// Hide Camera Bar — Foundry VTT V14
// Mostra ou esconde a barra de câmeras AV (#camera-views).
(async () => {
  const cameras = document.getElementById("camera-views");

  if (!cameras) {
    await foundry.applications.api.DialogV2.wait({
      window: { title: "Hide Camera Bar" },
      content: `<div style="padding:8px 2px;font-family:'Segoe UI',sans-serif;color:#f5e6d3;font-size:13px">
        <p style="color:#e84030;margin:0 0 6px">⚠ Elemento <code>#camera-views</code> não encontrado.</p>
        <p style="color:#c9a876;font-size:11px;margin:0;background:#1a1410;padding:6px 8px;border-radius:4px;border-left:2px solid #4a3a28">
          A barra de câmeras não está disponível no momento.
          Verifique se o módulo AV/WebRTC está ativo, ou se outro módulo removeu o elemento da interface.
        </p>
      </div>`,
      buttons: [{ action:"ok", label:"OK", default:true, callback:()=>null }],
      rejectClose: false,
    });
    return;
  }

  const isVisible = cameras.style.display !== "none";
  const actionLabel = isVisible ? "🙈 Esconder" : "👁 Mostrar";

  const ok = await foundry.applications.api.DialogV2.wait({
    window: { title: "Hide Camera Bar" },
    content: `<div style="padding:8px 2px;font-family:'Segoe UI',sans-serif;color:#f5e6d3;font-size:13px">
      <p style="margin:0 0 8px">${actionLabel} a <strong style="color:#f5d9a8">barra de câmeras</strong>?</p>
      <p style="font-size:11px;color:#8a6a4a;margin:0;background:#1a1410;padding:6px 8px;border-radius:4px;border-left:2px solid #4a3a28">
        ⚠ Funciona apenas enquanto o elemento estiver na interface.
        Se a barra não reaparecer ao usar "Mostrar", recarregue a página.
      </p>
    </div>`,
    buttons: [
      { action:"yes", label: actionLabel, default:true, callback:()=>true  },
      { action:"no",  label:"Cancelar",               callback:()=>false },
    ],
    rejectClose: false,
  });

  if (!ok) return;

  cameras.style.display = isVisible ? "none" : "flex";
  ui.notifications.info(`Barra de câmeras: ${isVisible ? "escondida 🙈" : "visível 👁"}`);
})();
